import * as React from "react";
export function useCloseOnEscape({
  open,
  onClose
}) {
  React.useEffect(() => {
    const close = e => {
      if (open && e.key === "Escape") {
        onClose?.();
      }
    };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, [open, onClose]);
}